<?php

namespace Database\Seeders;

use App\Models\Book;
use App\Models\BookGenre;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;

/** Books module: genres + a starter library (covers are generated by the React app). */
class BookSeeder extends Seeder
{
    public function run(): void
    {
        // slug => [name, icon, description, [ [title, author, year, synopsis], ... ]]
        $library = [
            'fantasy' => ['Fantasy', 'wand', 'Magic, myth and other worlds', [
                ['The Hobbit', 'J.R.R. Tolkien', 1937, 'Bilbo Baggins is swept into a quest with thirteen dwarves to reclaim a mountain kingdom from a dragon.'],
                ['The Name of the Wind', 'Patrick Rothfuss', 2007, 'Kvothe, a legendary figure, tells the story of his own rise from orphaned street child to magician.'],
                ['A Game of Thrones', 'George R.R. Martin', 1996, 'Noble families fight for the Iron Throne while an ancient threat stirs beyond the Wall.'],
                ['Harry Potter and the Sorcerer\'s Stone', 'J.K. Rowling', 1997, 'An orphan discovers he is a wizard and begins his first year at Hogwarts.'],
                ['The Lion, the Witch and the Wardrobe', 'C.S. Lewis', 1950, 'Four siblings step through a wardrobe into Narnia, a land frozen in endless winter.'],
            ]],
            'science-fiction' => ['Science Fiction', 'rocket', 'Futures, space and big ideas', [
                ['Dune', 'Frank Herbert', 1965, 'Paul Atreides must survive politics, betrayal and the deadly desert planet Arrakis.'],
                ['Neuromancer', 'William Gibson', 1984, 'A washed-up hacker is hired for one last job in a world of cyberspace and artificial intelligence.'],
                ['The Martian', 'Andy Weir', 2011, 'Stranded alone on Mars, astronaut Mark Watney uses science and humour to stay alive.'],
                ['Ender\'s Game', 'Orson Scott Card', 1985, 'A gifted child is trained in a military space academy to defend humanity from an alien threat.'],
                ['Foundation', 'Isaac Asimov', 1951, 'A mathematician predicts the fall of a galactic empire and creates a plan to shorten the dark age that follows.'],
            ]],
            'mystery-thriller' => ['Mystery & Thriller', 'search', 'Twists, clues and suspense', [
                ['And Then There Were None', 'Agatha Christie', 1939, 'Ten strangers are lured to an island and begin to die one by one.'],
                ['The Girl with the Dragon Tattoo', 'Stieg Larsson', 2005, 'A journalist and a gifted hacker investigate a decades-old disappearance inside a wealthy family.'],
                ['Gone Girl', 'Gillian Flynn', 2012, 'On their anniversary, a woman vanishes and her husband becomes the prime suspect.'],
                ['The Da Vinci Code', 'Dan Brown', 2003, 'A symbologist races across Europe to decode clues hidden in famous works of art.'],
                ['The Hound of the Baskervilles', 'Arthur Conan Doyle', 1902, 'Sherlock Holmes investigates a family curse and a spectral hound on the moors.'],
            ]],
            'romance' => ['Romance', 'heart', 'Love stories for every mood', [
                ['Pride and Prejudice', 'Jane Austen', 1813, 'Elizabeth Bennet and Mr. Darcy must overcome first impressions and social expectations.'],
                ['Outlander', 'Diana Gabaldon', 1991, 'A World War II nurse is swept back to 18th-century Scotland and into a new love.'],
                ['The Notebook', 'Nicholas Sparks', 1996, 'An elderly man reads from a worn notebook the story of a summer romance that lasted a lifetime.'],
                ['Me Before You', 'Jojo Moyes', 2012, 'A young caregiver and a man she looks after change each other\'s view of life.'],
                ['Jane Eyre', 'Charlotte Brontë', 1847, 'An orphaned governess finds love and mystery at Thornfield Hall.'],
            ]],
            'horror' => ['Horror', 'skull', 'Classic and modern chills', [
                ['Dracula', 'Bram Stoker', 1897, 'A group of friends unite to hunt the vampire Count Dracula after he arrives in England.'],
                ['Frankenstein', 'Mary Shelley', 1818, 'Victor Frankenstein creates life and then must face the consequences of his creation.'],
                ['The Shining', 'Stephen King', 1977, 'A family becomes caretakers of an isolated hotel where something malevolent waits.'],
                ['It', 'Stephen King', 1986, 'A group of friends confronts a shape-shifting evil that haunts their town every generation.'],
                ['Bird Box', 'Josh Malerman', 2014, 'A mother and two children must travel blindfolded through a world where seeing means danger.'],
            ]],
            'history' => ['History & Biography', 'landmark', 'Real stories that shaped the world', [
                ['Sapiens', 'Yuval Noah Harari', 2011, 'A sweeping history of humankind, from the Stone Age to the modern day.'],
                ['Guns, Germs, and Steel', 'Jared Diamond', 1997, 'Why some societies advanced faster than others - a look at geography, agriculture and disease.'],
                ['The Diary of a Young Girl', 'Anne Frank', 1947, 'The diary of a teenager hiding with her family in Amsterdam during World War II.'],
                ['A People\'s History of the United States', 'Howard Zinn', 1980, 'American history told from the perspective of ordinary and marginalised people.'],
                ['Long Walk to Freedom', 'Nelson Mandela', 1994, 'The autobiography of Nelson Mandela, from his childhood to the end of apartheid.'],
            ]],
            'self-improvement' => ['Self-Improvement', 'lightbulb', 'Habits, mindset and growth', [
                ['Atomic Habits', 'James Clear', 2018, 'A practical system for building good habits and breaking bad ones through tiny changes.'],
                ['The 7 Habits of Highly Effective People', 'Stephen R. Covey', 1989, 'Seven principles for personal and professional effectiveness.'],
                ['Deep Work', 'Cal Newport', 2016, 'Rules for focused success in a distracted world.'],
                ['Mindset', 'Carol S. Dweck', 2006, 'How a growth mindset can change the way we learn and succeed.'],
                ['How to Win Friends and Influence People', 'Dale Carnegie', 1936, 'Timeless advice on communication, relationships and leadership.'],
            ]],
            'adventure' => ['Adventure', 'compass', 'Journeys, survival and discovery', [
                ['Treasure Island', 'Robert Louis Stevenson', 1883, 'Young Jim Hawkins sails in search of buried pirate treasure and meets Long John Silver.'],
                ['The Count of Monte Cristo', 'Alexandre Dumas', 1844, 'Wrongly imprisoned, Edmond Dantès escapes and plans an elaborate revenge.'],
                ['Life of Pi', 'Yann Martel', 2001, 'A boy survives 227 days at sea on a lifeboat with a Bengal tiger.'],
                ['Into the Wild', 'Jon Krakauer', 1996, 'The true story of Christopher McCandless, who walked into the Alaskan wilderness.'],
                ['Around the World in Eighty Days', 'Jules Verne', 1872, 'Phileas Fogg bets he can circle the globe in eighty days.'],
            ]],
        ];

        $order = 0;
        foreach ($library as $slug => [$name, $icon, $description, $books]) {
            $genre = BookGenre::updateOrCreate(
                ['slug' => $slug],
                ['name' => $name, 'icon' => $icon, 'description' => $description, 'sort_order' => $order++]
            );

            foreach ($books as [$title, $author, $year, $synopsis]) {
                Book::updateOrCreate(
                    ['slug' => Str::slug($title)],
                    ['genre_id' => $genre->id, 'title' => $title, 'author' => $author, 'year' => $year, 'synopsis' => $synopsis]
                );
            }
        }
    }
}
